from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from cacheops import invalidate_obj
from .models import EnterpriseContract

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def invalidate_contract_cache(request):
    contract_id = request.data.get('contract_id')
    try:
        # Scope contract lookup strictly to the authenticated caller's organization
        contract = EnterpriseContract.objects.get(id=contract_id, organization=request.user.organization)
    except EnterpriseContract.DoesNotExist:
        return Response({'error': 'Contract not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

    invalidate_obj(contract)
    return Response({'status': 'invalidated', 'contract_id': contract.id})
